from collections import deque
def solve(g):
    H,W=len(g),len(g[0])
    # flood fill 1s reachable from outside through 1s; walls 2
    vis=[[False]*W for _ in range(H)]
    dq=deque()
    for i in range(H):
        for j in (0,W-1):
            if g[i][j]==1: vis[i][j]=True; dq.append((i,j))
    for j in range(W):
        for i in (0,H-1):
            if g[i][j]==1: vis[i][j]=True; dq.append((i,j))
    while dq:
        i,j=dq.popleft()
        for di,dj in ((1,0),(-1,0),(0,1),(0,-1)):
            a,b=i+di,j+dj
            if 0<=a<H and 0<=b<W and g[a][b]==1 and not vis[a][b]:
                vis[a][b]=True; dq.append((a,b))
    return [[3 if v==1 and not vis[i][j] else v for j,v in enumerate(row) ] for i,row in enumerate(g)]
